Lemma rc_svc1_regs : forall ms, svc1 ms -> ms_svc_pending ms = Some (Z_to_bv 64 222)
  /\ areg ms 10 = Z_to_bv 64 (rb SB c + mu) /\ areg ms 11 = Z_to_bv 64 msz /\ areg ms 12 = Z_to_bv 64 3 /\ areg ms 13 = Z_to_bv 64 50
